function loadSettings(){state.settings=storage.get(STORAGE.SETTINGS,{});var s=state.settings;applyTheme(s.theme||'system');state.anims=s.anims!==false;state.sortBy=s.sortBy||'order';state.categoryFilter=s.categoryFilter||'all';state.filter=s.filter||'all';state.groupByCategory=!!s.groupByCategory;state._categoriesOpen=s._categoriesOpen||{};if(el.themeSel)el.themeSel.value=s.theme||'system';if(el.animToggle)el.animToggle.checked=state.anims;if(el.groupToggle)el.groupToggle.checked=state.groupByCategory;if(el.dateFormat)el.dateFormat.value=s.dateFormat||'DD.MM.YYYY';if(el.weekStart)el.weekStart.value=String(s.weekStart!=null?s.weekStart:1);if(el.notifEnabled)el.notifEnabled.checked=s.notifEnabled!==false;if(el.notifPeriod)el.notifPeriod.value=String(s.notifPeriod!=null?s.notifPeriod:3);if(el.praiseEnabled)el.praiseEnabled.checked=s.praiseEnabled!==false;if(el.praiseInterval)el.praiseInterval.value=String(s.praiseInterval||30);applyAnimPref()}
function saveSettings(){state.settings={theme:el.themeSel?el.themeSel.value:'system',anims:el.animToggle?el.animToggle.checked:true,sortBy:state.sortBy,categoryFilter:state.categoryFilter,filter:state.filter,groupByCategory:el.groupToggle?el.groupToggle.checked:false,dateFormat:el.dateFormat?el.dateFormat.value:'DD.MM.YYYY',weekStart:el.weekStart?parseInt(el.weekStart.value):1,notifEnabled:el.notifEnabled?el.notifEnabled.checked:true,notifPeriod:el.notifPeriod?parseInt(el.notifPeriod.value):3,praiseEnabled:el.praiseEnabled?el.praiseEnabled.checked:true,praiseInterval:el.praiseInterval?parseInt(el.praiseInterval.value):30,_categoriesOpen:state._categoriesOpen};storage.set(STORAGE.SETTINGS,state.settings)}
function applyTheme(t){document.body.classList.remove('lt');if(t==='light')document.body.classList.add('lt');else if(t==='system'&&window.matchMedia('(prefers-color-scheme:light)').matches)document.body.classList.add('lt')}
function applyAnimPref(){document.body.classList.toggle('no-anim',!state.anims)}
function notify(timer,body,type){toast.show(timer.title+' — '+body,type)}
function checkNotifications(now){if(state.settings.notifEnabled===false)return;var ts=now.getTime();var period=state.settings.notifPeriod!=null?state.settings.notifPeriod:3;var pe=state.settings.praiseEnabled!==false;var pi=state.settings.praiseInterval||30;var changed=false,shown=0;var MAX=3;for(var i=0;i<state.timers.length;i++){var t=state.timers[i];if(isDnd(t.id))continue;var type=resolveType(t.date);if(type==='countdown'&&t.reminder){var dl=Math.ceil((t.date-ts)/DAY_MS);var ps=[period,1,0];if(dl>=0&&ps.indexOf(dl)!==-1){var k='r_'+t.id+'_'+dl;if(!state.notified[k]){state.notified[k]=true;changed=true;if(shown<MAX){notify(t,dl===0?'сегодня':'осталось '+declension(dl,['день','дня','дней']),'info');shown++}}}}if(type==='elapsed'&&pe){var ed=Math.floor((ts-t.date)/DAY_MS);if(ed>0){var lk='p_last_'+t.id;var lp=state.notified[lk]||0;var ms=Math.floor(ed/pi)*pi;if(ms>lp&&ms>0){state.notified[lk]=ms;changed=true;if(shown<MAX){notify(t,declension(ms,['день','дня','дней'])+'! Отличная работа!','success');celebrate(t.color);shown++}}}}}if(changed)saveNotified()}
function checkRecurring(now){var changed=false;for(var i=0;i<state.timers.length;i++){var t=state.timers[i];if(!t.recurring)continue;if(resolveType(t.date)!=='countdown')continue;if(now.getTime()-t.date>100*365*DAY_MS){t.date=now.getTime();changed=true;continue}var g=0;while(now.getTime()>t.date&&g<2000){var d=new Date(t.date);if(t.recurring==='weekly')d.setDate(d.getDate()+7);else if(t.recurring==='monthly'){var day=t.originalDay||d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}else if(t.recurring==='yearly'){var d2=t.originalDay||d.getDate();d.setDate(1);d.setMonth(0);d.setFullYear(d.getFullYear()+1);d.setDate(Math.min(d2,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}else break;t.date=d.getTime();changed=true;g++}}if(changed)persist()}
function findTimer(id){return state.timers.find(function(x){return x.id===id})}
function getCard(id){return el.timerList?el.timerList.querySelector('.tc-card[data-id="'+id+'"]'):null}
function buildBadge(cls,label){return'<span class="badge '+cls+'">'+esc(label)+'</span>'}
function buildCardBadges(t){var type=resolveType(t.date);var p=[];if(t.category&&CAT_NAMES[t.category])p.push(buildBadge('cat-tag '+t.category,CAT_NAMES[t.category]));if(t.recurring&&REC_NAMES[t.recurring])p.push(buildBadge('recurring-badge',REC_NAMES[t.recurring]));if(isDnd(t.id))p.push(buildBadge('dnd-badge','🔇 Тихо'));p.push(buildBadge('tc-type '+(type==='elapsed'?'elapsed':'countdown'),type==='elapsed'?'Прошло':'Осталось'));return p.join('')}
function createTimerCard(t){var type=resolveType(t.date);var color=sanitizeColor(t.color);var card=document.createElement('div');card.className='tc-card'+(isDnd(t.id)?' muted':'');card.dataset.id=t.id;card.setAttribute('role','listitem');card.innerHTML='<div class="tc-swipe-actions"><button class="tc-swipe-edit" data-id="'+t.id+'" aria-label="Редактировать">'+ICONS.edit+'Изменить</button><button class="tc-swipe-delete" data-id="'+t.id+'" aria-label="Удалить">'+ICONS.trash+'Удалить</button></div><div class="tc-swipe-content"><div class="tc-handle" aria-label="Перетащить" title="Перетащить">'+ICONS.drag+'</div><div class="tc-body"><div class="tc-row-top"><div class="tc-title">'+esc(t.title)+'</div><div class="tc-actions"><button class="ibtn-s mute'+(isDnd(t.id)?' active':'')+'" data-id="'+t.id+'" title="Не беспокоить">'+(isDnd(t.id)?ICONS.mute:ICONS.bell)+'</button><button class="ibtn-s ed" data-id="'+t.id+'" title="Редактировать">'+ICONS.edit+'</button><button class="ibtn-s dl" data-id="'+t.id+'" title="Удалить">'+ICONS.trash+'</button><button class="ibtn-s dup" data-id="'+t.id+'" title="Дублировать">'+ICONS.duplicate+'</button></div></div><div class="tc-badges">'+buildCardBadges(t)+'</div><div class="tc-counter"><div class="tc-counter-val" data-ts="'+t.date+'" data-type="'+type+'" style="color:'+color+'"></div></div><div class="tc-date">'+ICONS.calendarPicker+formatDate(t.date)+'</div></div></div>';return card}
function updateCardCounter(card){var c=card.querySelector('.tc-counter-val');if(!c)return;var ts=parseInt(c.dataset.ts);if(!ts)return;var type=resolveType(ts);c.dataset.type=type;var now=Date.now();var diff=type==='countdown'?ts-now:now-ts;var nt=fmtCounter(ts,type);if(c.textContent!==nt)c.textContent=nt;var u=type==='countdown'&&diff>0&&diff<60000;if(card.classList.contains('urgent')!==u)card.classList.toggle('urgent',u)}
function getFiltered(){var key=state.filter+'|'+state.categoryFilter+'|'+state.searchQuery+'|'+state.sortBy+'|'+state._lastTimersChange+'|'+state.timers.length;if(state._filterCache.key===key&&state._filterCache.result)return state._filterCache.result;var f=state.timers.slice();if(state.filter!=='all')f=f.filter(function(x){return resolveType(x.date)===state.filter});if(state.categoryFilter!=='all'){f=state.categoryFilter===''?f.filter(function(x){return!x.category}):f.filter(function(x){return x.category===state.categoryFilter})}if(state.searchQuery){var q=normalize(state.searchQuery);f=f.filter(function(x){return normalize(x.title).indexOf(q)!==-1})}if(state.sortBy==='name')f.sort(function(a,b){return a.title.localeCompare(b.title,'ru',{numeric:true,sensitivity:'base'})});else if(state.sortBy==='date')f.sort(function(a,b){return a.date-b.date});else if(state.sortBy==='created')f.sort(function(a,b){return(b.created||0)-(a.created||0)});state._filterCache={key:key,result:f};return f}
function setEmptyState(kind){var h=$('emptyTitle'),p=$('emptyBody'),b=el.emptyBtn;if(!h||!p||!b)return;if(kind==='noResults'){h.textContent=TEXTS.noResultsTitle;p.textContent=TEXTS.noResultsBody;b.textContent=TEXTS.noResultsBtn;b.onclick=resetFilters}else{h.textContent=TEXTS.emptyTitle;p.textContent=TEXTS.emptyBody;b.textContent=TEXTS.emptyBtn;b.onclick=openTimerModalFromUI}}
function resetFilters(){state.filter='all';state.categoryFilter='all';state.searchQuery='';if(el.searchInput)el.searchInput.value='';if(el.searchClear)el.searchClear.classList.add('hidden');saveSettings();render()}
function render(){var filtered=getFiltered();updateFilterButtonState();if(intersectionObserver){intersectionObserver.disconnect();visibleCards.clear()}var wasFirst=!state.firstRenderDone;state.firstRenderDone=true;if(filtered.length===0){el.timerList.innerHTML='';el.emptyState.classList.remove('hidden');if(el.heroCta)el.heroCta.classList.remove('hidden');var isF=state.filter!=='all'||state.categoryFilter!=='all'||state.searchQuery;setEmptyState(isF?'noResults':'empty');return}el.emptyState.classList.add('hidden');if(el.heroCta)el.heroCta.classList.add('hidden');el.timerList.innerHTML='';if(state.groupByCategory&&state.sortBy==='order'&&filtered.length>1)renderGrouped(filtered);else renderFlat(filtered);var cards=el.timerList.querySelectorAll('.tc-card');for(var i=0;i<cards.length;i++){observeCard(cards[i]);if(!wasFirst)cards[i].classList.add('no-anim');updateCardCounter(cards[i])}}
