function openModalById(id){var m=$(id);if(!m)return;state._lastFocus=document.activeElement;var we=state._modalStack.length===0;state._modalStack.push(id);if(we)history.pushState({chronoflow_modal:true},'');else history.replaceState({chronoflow_modal:true,depth:state._modalStack.length},'');m.classList.add('show');document.body.classList.add('modal-open');trapFocus(m)}
